            (7,4,"'차이나 쇼크 때 중국 주식 사면 3년 후 두 배' — 결과론적 저점 매수의 위험",
             "훗날 일부 투자자들은 '차이나 쇼크 바닥에서 중국 주식을 사서 3년 보유하면 큰 수익'이라고 주장합니다. "
             "틀린 말은 아닙니다. 하지만 '바닥'이 어딘지 당시에는 아무도 몰랐으며, "
             "바닥이 지났다고 생각할 때마다 추가 하락이 이어졌습니다. "
             "👉 결과론으로 저점을 판단하면 안 됩니다. 위기 중에는 방향이 바뀐 신호가 확인될 때까지 기다려야 합니다.","군중심리"),
            (7,5,"'차이나 쇼크 이후 반등, 이미 중국 저점에서 시작됐다' — 뒤늦은 진입의 함정",
             "차이나 쇼크가 지나고 중국 증시가 일부 반등하자 '이제 중국 매수 타이밍'이라는 주장이 다시 등장했습니다. "
             "그러나 뒤늦게 진입한 투자자들은 이후 중국 증시가 저점을 깨고 추가 하락하는 것을 경험했습니다. "
             "위기 국면이 끝났다는 신호와 투자 적기는 반드시 일치하지 않습니다.","군중심리"),
