            (5,1,"태영건설 워크아웃 공식 신청 — 국내 10위권 건설사, PF 부실 현실화",
             "2023년 12월, 국내 시공능력 10위권의 태영건설이 채권단에 워크아웃(기업개선작업)을 공식 신청했습니다. "
             "PF 부실이 주요 원인으로, PF 보증 채무 규모가 수조 원에 달한다는 분석이 나왔습니다. "
             "'대형 건설사는 절대 망하지 않는다'는 통념이 깨지면서 시장 공포가 최고조에 달했습니다. "
             "달러/원 환율이 1,422원까지 급등했습니다.","거시"),
