            (3,2,"개입 발표에 주식·코인·리츠 5~10% 반등…'데드 캣 바운스' 경계",
             "당국 개입 발표에 주식·코인·리츠가 일제히 5~10% 반등했습니다. '드디어 바닥을 찍었다'는 기대가 커지고 있습니다. "
             "하지만 블랙스완에서 이런 일시적 반등을 '데드 캣 바운스'라고 부릅니다. 죽은 고양이도 높은 곳에서 떨어지면 한 번 튀어 오르듯, 폭락 후 일시적 반등이 추세 전환을 의미하지는 않습니다. "
             "당국 개입의 효과가 지속될지는 내일 시장이 증명할 것입니다.","데드캣"),
            (3,3,"'폭락장 용감한 매수가 기회'…블랙스완서 2008식 추가 손실 전례",
             "반등을 보고 '이렇게 폭락한 자산을 이 가격에 살 수 있다니, 용감한 투자자라면 지금 사야 한다'는 목소리가 나오고 있습니다. "
             "용기 있는 투자가 때로는 큰 수익으로 이어지지만, 블랙스완의 본질적 위기가 해소되지 않은 상황에서는 다릅니다. "
             "2008년 리먼 사태 때도 이런 반등이 여러 번 있었고, 그때마다 '지금이 기회'라고 산 투자자들은 더 큰 손실을 입었습니다. "
             "블랙스완에서는 '용감함'이 아닌 '인내와 현금 보유'가 미덕입니다.","저점매수"),
            (3,4,"금·채권 소폭 반등에 '안전 자산 피신' 권유…2차 충격 시 재매도 위험",
             "오늘 금과 채권도 소폭 반등했습니다. '금과 채권은 역시 안전하다, 지금 이리로 피해야 한다'는 조언이 나오고 있습니다. "
             "하지만 블랙스완 2차 충격이 도래하면 금과 채권도 다시 매도 대상이 됩니다. "
             "오늘의 반등이 진짜 안전 자산으로의 회귀인지, 아니면 내일 다시 팔릴 일시적 반등인지를 알 방법이 없습니다. "
             "블랙스완에서 금·채권으로 이동하는 것은 또 다른 위험을 택하는 것입니다.","안전자산"),
            (3,5,"VIX 58→49 하락에 '공포 고점 확인' 분석…2008년 재상승 전례",
             "VIX가 어제 58에서 오늘 49로 내려오자 '공포 지수가 고점을 찍었다, 이제 안정될 것'이라는 분석이 나왔습니다. "
             "VIX 고점 확인이 시장 바닥과 일치하는 경우도 있지만, 블랙스완에서는 다릅니다. "
             "2008년 리먼 사태 때 VIX는 여러 번 '고점 확인'처럼 보였다가 더 높이 치솟았습니다. "
             "블랙스완은 예측 불가능한 것이 본질입니다. VIX 숫자 하나로 '최악은 지나갔다'고 단정하는 것은 위험합니다.","공포지수"),

            # Day 4 (5 traps — ALL slots)
            (4,1,"2차 충격 현실화…D3 반등분 전량 반납, 당국 개입 효과 소멸",
             "D3 당국의 긴급 개입에도 불구하고 오늘 위기가 재확산되며 2차 충격이 도래했습니다. "
             "어제 반등했던 모든 자산이 오늘 다시 급락하며 D3의 반등이 '데드 캣 바운스'였음이 확인됐습니다. "
             "D3에 반등을 보고 매수에 나섰던 투자자들이 이틀 만에 다시 손실을 입었습니다. "
             "블랙스완에서는 당국 개입도, 일시적 반등도 믿지 않는 것이 원칙입니다.","정책개입"),
            (4,2,"'상대적 강세 국채로 피신' 권유…마진콜 충당 대량 매도 우려",
             "오늘 국채가 다른 자산에 비해 상대적으로 덜 하락하자 '국채는 역시 안전하다, 지금 국채로 피하는 게 맞다'는 조언이 나오고 있습니다. "
             "하지만 블랙스완 2차 충격에서는 국채도 함께 폭락하는 경우가 있습니다. "
             "극도의 유동성 위기에서 기관들이 마진콜 충당을 위해 가장 유동성이 좋은 국채까지 팔아치우기 때문입니다. "
             "'상대적으로 덜 떨어진다'는 것이 '안전하다'는 의미는 아닙니다.","채권피신"),
            (4,3,"'패닉셀 하면 반등 놓친다' 경고…블랙스완선 버티기도 위험",
             "역사적으로 패닉셀을 한 투자자들이 결국 반등을 놓치고 후회했다는 사례들이 소개되고 있습니다. "
             "'두려움에 팔면 안 된다, 버텨야 한다'는 조언입니다. "
             "평상시 약세장에서는 맞는 말이지만, 블랙스완은 '역사적 패턴'이 통하지 않는 특수 상황입니다. "
             "블랙스완에서 버티는 것은 용기가 아닐 수 있습니다. 추가 폭락이 이어질 때 버티면 손실이 더욱 커집니다.","패닉셀"),
            (4,4,"달러 잠시 강세에 '달러 자산 갈아타기' 권유…현금 보유와 혼동 주의",
             "달러가 잠시 강세를 보이며 '달러 자산이 안전하다, 지금 달러로 이동하는 게 맞다'는 조언이 나오고 있습니다. "
             "달러 자체는 블랙스완에서 상대적으로 강한 편이지만, '달러 자산'으로 이동하는 과정에서 더 큰 손실이 날 수 있습니다. "
             "가장 안전한 달러 보유 방법은 달러 현금이지, 달러 표시 주식이나 채권이 아닙니다. "
             "지금 자산을 팔아 달러로 이동하는 과정에서의 손실보다, 처음부터 현금을 들고 있었던 것이 훨씬 낫습니다.","달러자산"),
            (4,5,"'코로나·911처럼 1~2개월 내 회복' 낙관론…2008년 5년 장기화 전례",
             "과거 코로나(2020년 3월), 911 테러(2001년) 등 충격적 사건 직후 시장이 빠르게 회복된 사례를 들며 '1~2개월 후면 회복된다'는 낙관론이 나오고 있습니다. "
             "하지만 진짜 블랙스완은 '단기 충격'과 차원이 다릅니다. 2008년 금융위기는 회복에 5년이 걸렸습니다. "
             "'1개월 후 회복'을 믿고 지금 매수하면, 회복이 5년 뒤에 올 때까지 손실을 감내해야 할 수 있습니다. "
             "블랙스완의 회복 타이밍은 아무도 예측할 수 없습니다.","회복기대"),

            # Day 5 (4 traps — slots 2,3,4,5)
            (5,1,"VIX 85 돌파…2008 최악 수준, 글로벌 서킷브레이커 발동 거래 마비",
             "공포 지수(VIX)가 85를 돌파했습니다. 이는 2008년 금융위기 최악의 순간과 동일한 수준입니다. "
             "주요 글로벌 거래소에서 자동 서킷브레이커가 발동되며 거래 자체가 마비됐습니다. "
             "많은 투자자들이 계좌를 열어보지 못하고 있으며, 일부는 반강제적으로 마진콜 청산을 당하고 있습니다. "
             "처음부터 현금 비중을 최대로 유지했던 사람만이 이 폭풍에서 자유롭습니다.","시황"),
            (5,2,"코인 -25%·주식 -18%·금 -8%…전면 패닉 셀, 현금만 유일한 방어",
             "오늘은 7일 중 가장 혼란스러운 날입니다. 현금 외에 모든 자산이 크게 하락했습니다. "
             "코인 -25%, 주식 -18%, 리츠 -20%, 원유 -15%, 금 -8%, 채권 -6% 등 전면적인 패닉 셀이 진행됐습니다. "
             "아직도 위험 자산을 들고 있다면, 지금이라도 비중을 줄이는 것이 추가 손실을 막는 길입니다. "
             "블랙스완은 '더 내려가지 않을 것'이라는 예측을 허용하지 않습니다.","현금"),
            (5,3,"원유 누적 -30%에 '저점 매수 기회' 주장…추가 -20% 가능성 경고",
             "원유가 시나리오 시작 이후 30% 가까이 폭락하자 '이 가격에 원유를 사면 장기적으로 반드시 오른다'는 저점 매수 목소리가 나오고 있습니다. "
             "장기적으로는 맞는 말일 수 있습니다. 하지만 지금 사면 얼마나 더 내려갈지 알 수 없습니다. "
             "-30%가 -50%가 될 수도 있습니다. 블랙스완에서 저점 매수는 '바닥 잡기'인데, 바닥은 아무도 모릅니다.","저점매수"),
            (5,4,"비트코인 반토막에 '장기 보유' 권유…블랙스완서 -80% 전례 경고",
             "비트코인이 시나리오 시작 대비 반토막이 난 상황에서 '이미 반값이니 이제 사서 장기 보유하면 된다'는 조언이 나오고 있습니다. "
             "하지만 반값이 된 자산은 다시 반값이 될 수 있습니다. 블랙스완에서 코인은 -80, -90%까지 내려간 역사가 있습니다. "
             "'장기 보유'라는 전략이 맞더라도, 블랙스완이 진행 중인 지금 사는 것은 수개월~수년간의 손실을 감내하는 선택입니다.","장기보유"),
            (5,5,"'손실 확정 두려워 버티자' 심리…추가 하락 시 손실 심화 우려",
             "이미 큰 손실을 입은 상황에서 '지금 팔면 손실이 확정된다, 조금만 더 기다리면 회복되지 않겠어'라는 생각이 드는 것은 자연스럽습니다. "
             "이를 '손실 회피 편향'이라고 합니다. 하지만 블랙스완 환경에서는 '기다리는 동안' 추가 하락이 계속될 수 있습니다. "
             "이미 -30%인데 -60%가 되는 것보다, 지금 -30%에 팔고 현금을 지키는 것이 훨씬 나을 수 있습니다. "
             "손실 확정이 두렵더라도 추가 손실 방지가 우선입니다.","손실회피"),

            # Day 6 (3 traps — slots 3,4,5)
            (6,1,"중앙은행 재할인 창구 개방·긴급 국채 매입…패닉 일시 진정",
             "중앙은행이 재할인 창구를 전면 개방하고 국채 긴급 매입 프로그램을 발동했습니다. 정부도 긴급 금융 안정 패키지를 발표했습니다. "
             "이 소식에 시장이 일시적으로 진정되며 주요 자산들이 소폭 반등했습니다. "
             "하지만 위기의 본질적 원인이 해소된 것은 아닙니다. 당국의 유동성 공급이 단기 패닉을 진정시킬 수 있지만, 블랙스완의 근본 위기를 제거하지는 못합니다.","시황"),
            (6,2,"현금 0% 손실…코인 -43%·주식 -33% 속 유일한 가치 보존",
             "7일간의 혼란 속에서 처음부터 현금 비중을 최대로 유지했던 투자자들이 유일한 승자입니다. "
             "코인은 -43%, 주식은 -33%, 리츠는 -29%의 손실을 기록하는 동안 현금은 단 1원도 잃지 않았습니다. "
             "'아무것도 하지 않는 것'이 블랙스완에서는 가장 현명한 행동이었습니다. 현금 비중 극대화가 이 시나리오의 유일한 정답입니다.","현금"),
            (6,3,"'당국 유동성 공급에 바닥 확인' 분석…D3 매수자 D4 재손실 전례",
             "중앙은행의 대규모 유동성 공급에 시장이 반응하자 '이제 바닥이 확인됐다, 저가 매수 기회'라는 분석이 쏟아지고 있습니다. "
             "유동성 공급은 패닉을 일시 진정시킬 수 있지만, 블랙스완의 바닥은 당국의 개입으로 결정되지 않습니다. "
             "D3에도 비슷한 상황이 있었고, 그때 매수한 투자자들은 D4에서 다시 큰 손실을 입었습니다. "
             "블랙스완 환경에서 바닥은 아무도 예측할 수 없습니다.","정책개입"),
            (6,4,"금 2%·채권 1.5% 소폭 반등에 '안전 자산 피신' 권유…데드 캣 경계",
             "오늘 금이 2%, 채권이 1.5% 소폭 반등하자 '안전 자산이 회복되고 있다, 지금 이리로 피해야 한다'는 조언이 나오고 있습니다. "
             "하지만 이번 시나리오에서 금은 누적 -7%, 채권은 -5%의 손실을 기록하고 있습니다. "
             "오늘의 소폭 반등이 지속적인 회복의 시작인지, 또 다른 데드 캣 바운스인지 알 수 없습니다. "
             "블랙스완에서 금·채권으로 이동하는 것은 현금보다 열등한 선택입니다.","안전자산"),
            (6,5,"VIX 85→72 하락에 '공포 피크아웃·반등 임박' 기대…여전히 극공포 구간",
             "VIX가 85에서 72로 내려오자 '공포 지수가 고점을 찍었다, 이제 반등이 온다'는 기대가 나오고 있습니다. "
             "VIX 72도 여전히 극도로 높은 수준입니다. 정상적인 시장의 VIX는 15~25 수준이며, 72는 여전히 공포 극점에 가깝습니다. "
             "블랙스완에서 VIX 하락이 반등의 신호인 경우도 있지만, 더 큰 폭락 직전에 잠시 내려온 경우도 많습니다. "
             "'VIX가 내려왔으니 안전하다'는 성급한 판단입니다.","공포지수"),

            # Day 7 (2 traps — slots 4,5)
            (7,1,"7일 결산 — 코인 -45%·주식 -35%·금 -7%…현금만 무손실",
             "7일간 코인 -45%, 주식 -35%, 리츠 -30%, 원유 -22%, 금 -7%, 채권 -5%를 기록했습니다. "
             "전통적인 '안전 자산'인 금과 채권마저 손실을 입었습니다. "
             "오직 현금만이 단 1원도 잃지 않고 7일을 버텼습니다. "
             "블랙스완의 교훈은 명확합니다: 아무것도 예측할 수 없는 극단적 상황에서는 '아무것도 하지 않는 것'이 최선입니다.","시황"),
            (7,2,"현금 0%·달러 +0.5%…코인·주식과 격차 35~45%p",
             "7일간 현금이 0%, 달러가 +0.5%를 기록하며 유일한 가치 보존 수단임이 입증됐습니다. "
             "코인 -45%, 주식 -35%와의 차이가 45%p, 35%p에 달합니다. "
             "블랙스완에서는 수익을 내는 것이 아니라 '덜 잃는 것'이 승리입니다. "
             "처음부터 현금 비중을 최대로 유지한 투자자들이 이번 시나리오의 절대적인 승자입니다.","현금"),
